INSERT OR IGNORE INTO deep_dive_page_translations (country_id, lang, compliance_model, footer_disclaimer, timeline_intro, file_format_intro, scope_intro, steps_intro, penalties_intro, mandate_summary, mandate_summary_icon)
SELECT id, 'en', 'Real-time clearance to the AGT via certified software', 'This page rests on Decreto Presidencial 71/25 read article by article, on the Código Geral Tributário for the retention period, and on Angolan reporting for commencement dates the instruments do not fix. The Ministry of Finance publishes the decree as a PDF with no text layer and its own commencement announcement returned no readable body, so both were left uncited rather than cited unread.', 'Three postponements and two clocks. The decree took effect in September 2025 with a transitional window, the first phase commenced in January 2026, and the second has a statutory date and a practical one that do not match.', 'JSON to the AGT, not XML. There is no UBL, no EN 16931 and no Peppol authority. The document carries a QR code and a digital code the AGT defines, applied by certified software.', 'The obligation follows the VAT regime, not the customer. Every taxpayer in the General and Simplified regimes is caught eventually; the phases decide only who is caught yet.', 'Most of the work is registration rather than integration. Nothing can be issued until the software is certified, the taxpayer has joined, every establishment is declared and a series exists for each one, in that order.', 'Penalties are a percentage of the invoice, not a fixed fine, so exposure scales with the value that went unrecorded. A first offence is halved, and the heaviest rate covers not issuing and SAF-T omissions.', 'Angola clears invoices in real time. Software validated by the tax authority transmits each document as it is issued, cannot delete it afterwards, and stamps it with a code the AGT defines. The duty attaches to the VAT regime rather than to the counterparty, so business, consumer and government sales are caught alike. Large taxpayers and State suppliers went first in January 2026; everyone else follows.', '🇦🇴' FROM countries WHERE code = 'AO';

INSERT OR IGNORE INTO deep_dive_page_translations (country_id, lang, compliance_model, footer_disclaimer, timeline_intro, file_format_intro, scope_intro, steps_intro, penalties_intro, mandate_summary, mandate_summary_icon)
SELECT id, 'es', 'Liquidación en tiempo real ante la AGT con software certificado', 'Esta página se apoya en el Decreto Presidencial 71/25 leído artículo por artículo, en el Código Geral Tributário para el plazo de conservación y en la prensa angoleña para las fechas de entrada que los instrumentos no fijan. El Ministerio de Finanzas publica el decreto en un PDF sin capa de texto y su propio anuncio de entrada no devolvió cuerpo legible, así que ambos se dejaron sin citar antes que citarlos sin leer.', 'Tres aplazamientos y dos relojes. El decreto surtió efecto en septiembre de 2025 con una ventana transitoria, la primera fase arrancó en enero de 2026 y la segunda tiene una fecha legal y otra práctica que no coinciden.', 'JSON hacia la AGT, no XML. No hay UBL, ni EN 16931, ni autoridad Peppol. El documento lleva un código QR y un código digital definido por la AGT que aplica el software certificado.', 'La obligación sigue al régimen de IVA y no al cliente. Todo contribuyente de los regímenes general y simplificado acaba alcanzado; las fases solo deciden a quién alcanzan ya.', 'La mayor parte del trabajo es registro, no integración. No se emite nada hasta que el software esté certificado, el contribuyente se haya adherido, cada establecimiento esté declarado y exista una serie para cada uno, por ese orden.', 'Las sanciones son un porcentaje de la factura y no una multa fija, así que la exposición crece con el valor no registrado. La primera infracción se reduce a la mitad, y el tipo más alto cubre no emitir y omitir el SAF-T.', 'Angola liquida las facturas en tiempo real. Un software validado por la administración tributaria transmite cada documento al emitirlo, no puede borrarlo después y le estampa un código que define la AGT. La obligación sigue al régimen de IVA y no a la contraparte, de modo que quedan alcanzadas por igual las ventas a empresas, a consumidores y al Estado. Los grandes contribuyentes y los proveedores del Estado entraron en enero de 2026; el resto viene después.', '🇦🇴' FROM countries WHERE code = 'AO';

INSERT OR IGNORE INTO deep_dive_page_translations (country_id, lang, compliance_model, footer_disclaimer, timeline_intro, file_format_intro, scope_intro, steps_intro, penalties_intro, mandate_summary, mandate_summary_icon)
SELECT id, 'de', 'Echtzeit-Clearing an die AGT über zertifizierte Software', 'Diese Seite stützt sich auf das Artikel für Artikel gelesene Präsidialdekret 71/25, auf den Código Geral Tributário für die Aufbewahrungsfrist und auf angolanische Presse für Termine, die die Instrumente nicht festlegen. Das Finanzministerium veröffentlicht das Dekret als PDF ohne Textebene, und seine eigene Bekanntmachung lieferte keinen lesbaren Text; beide bleiben deshalb unzitiert statt ungelesen zitiert.', 'Drei Verschiebungen und zwei Uhren. Das Dekret galt ab September 2025 mit einem Übergangsfenster, die erste Stufe begann im Januar 2026, und die zweite hat ein gesetzliches und ein praktisches Datum, die nicht übereinstimmen.', 'JSON an die AGT, nicht XML. Es gibt kein UBL, keine EN 16931 und keine Peppol-Behörde. Das Dokument trägt einen QR-Code und einen von der AGT definierten digitalen Code, den die zertifizierte Software setzt.', 'Die Pflicht folgt dem Umsatzsteuerregime, nicht dem Kunden. Am Ende ist jeder Steuerpflichtige des allgemeinen und des vereinfachten Regimes erfasst; die Stufen bestimmen nur, wer schon erfasst ist.', 'Der grösste Teil der Arbeit ist Registrierung, nicht Integration. Nichts lässt sich ausstellen, bevor die Software zertifiziert ist, der Steuerpflichtige beigetreten ist, jede Betriebsstätte gemeldet ist und für jede eine Serie besteht, in dieser Reihenfolge.', 'Sanktionen sind ein Prozentsatz der Rechnung und keine feste Busse, das Risiko wächst also mit dem nicht erfassten Wert. Der erste Verstoss wird halbiert, und der höchste Satz trifft Nichtausstellen wie SAF-T-Auslassungen.', 'Angola gibt Rechnungen in Echtzeit frei. Von der Steuerbehörde validierte Software übermittelt jedes Dokument bei der Ausstellung, kann es danach nicht löschen und versieht es mit einem von der AGT definierten Code. Die Pflicht folgt dem Umsatzsteuerregime und nicht der Gegenseite, sodass Verkäufe an Unternehmen, Verbraucher und den Staat gleichermassen erfasst sind. Grossunternehmen und Lieferanten des Staates begannen im Januar 2026; alle übrigen folgen.', '🇦🇴' FROM countries WHERE code = 'AO';

INSERT OR IGNORE INTO deep_dive_page_translations (country_id, lang, compliance_model, footer_disclaimer, timeline_intro, file_format_intro, scope_intro, steps_intro, penalties_intro, mandate_summary, mandate_summary_icon)
SELECT id, 'fr', 'Dédouanement en temps réel auprès de l''AGT, logiciel agréé', 'Cette page s''appuie sur le décret présidentiel 71/25 lu article par article, sur le Código Geral Tributário pour la durée de conservation, et sur la presse angolaise pour les dates d''entrée que les instruments ne fixent pas. Le ministère des Finances publie le décret en PDF sans couche texte et son propre avis d''entrée en vigueur n''a renvoyé aucun texte lisible : tous deux sont restés non cités plutôt que cités sans lecture.', 'Trois reports et deux horloges. Le décret a pris effet en septembre 2025 avec une fenêtre transitoire, la première phase a démarré en janvier 2026, et la seconde a une date légale et une date pratique qui ne coïncident pas.', 'Du JSON vers l''AGT, pas du XML. Ni UBL, ni EN 16931, ni autorité Peppol. Le document porte un code QR et un code numérique défini par l''AGT, apposé par le logiciel agréé.', 'L''obligation suit le régime de TVA et non le client. Tout assujetti des régimes général et simplifié finit par être visé ; les phases ne font que fixer qui l''est déjà.', 'L''essentiel du travail est de l''enregistrement, pas de l''intégration. Rien ne peut être émis avant que le logiciel soit agréé, le contribuable adhérent, chaque établissement déclaré et une série ouverte pour chacun, dans cet ordre.', 'Les sanctions sont un pourcentage de la facture et non une amende fixe : l''exposition croît avec la valeur non enregistrée. Une première infraction est réduite de moitié, et le taux le plus lourd frappe le défaut d''émission comme les omissions de SAF-T.', 'L''Angola valide les factures en temps réel. Un logiciel agréé par l''administration fiscale transmet chaque document dès son émission, ne peut plus le supprimer ensuite et y appose un code défini par l''AGT. L''obligation suit le régime de TVA et non la contrepartie : les ventes aux entreprises, aux particuliers et à l''État sont visées de la même façon. Les grandes entreprises et les fournisseurs de l''État ont commencé en janvier 2026 ; les autres suivent.', '🇦🇴' FROM countries WHERE code = 'AO';

