INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json)
SELECT d.id, 'en', 'Format & standard', '[["The format", "JSON, transmitted to the AGT by the issuing software or posted through the taxpayer portal. Not XML: there is no UBL profile and no EN 16931 alignment."], ["The network", "None. Angola has no Peppol authority and no four-corner exchange; the software talks to the tax authority directly."], ["What makes it valid", "A digital code defined by the AGT under article 19(2), applied by the certified software, plus a QR code on the printed or shared document."], ["What the software must do", "Article 17(2): transmit in real time, and refuse to delete a document once issued. Both are conditions of validation, not features."]]' FROM deep_dive_cards d WHERE d.country_id = (SELECT id FROM countries WHERE code = 'AO') AND d.section = 'file_format' AND d.sort_order = 0;
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json)
SELECT d.id, 'es', 'Formato y estándar', '[["El formato", "JSON, transmitido a la AGT por el software emisor o cargado en el portal del contribuyente. No es XML: no hay perfil UBL ni alineación con EN 16931."], ["La red", "Ninguna. Angola no tiene autoridad Peppol ni intercambio de cuatro esquinas; el software habla directamente con la administración tributaria."], ["Qué lo hace válido", "Un código digital definido por la AGT según el artículo 19(2), aplicado por el software certificado, más un código QR en el documento impreso o compartido."], ["Qué debe hacer el software", "Artículo 17(2): transmitir en tiempo real y no permitir borrar un documento ya emitido. Son condiciones de la validación, no funciones."]]' FROM deep_dive_cards d WHERE d.country_id = (SELECT id FROM countries WHERE code = 'AO') AND d.section = 'file_format' AND d.sort_order = 0;
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json)
SELECT d.id, 'de', 'Format und Standard', '[["Das Format", "JSON, von der ausstellenden Software an die AGT übermittelt oder über das Steuerportal eingestellt. Kein XML: kein UBL-Profil, keine Ausrichtung an EN 16931."], ["Das Netz", "Keines. Angola hat keine Peppol-Behörde und keinen Vier-Ecken-Austausch; die Software spricht direkt mit der Steuerbehörde."], ["Was es gültig macht", "Ein von der AGT nach Artikel 19(2) definierter digitaler Code, den die zertifizierte Software setzt, dazu ein QR-Code auf dem Dokument."], ["Was die Software leisten muss", "Artikel 17(2): in Echtzeit übermitteln und ein ausgestelltes Dokument nicht löschen können. Beides sind Bedingungen der Validierung, keine Funktionen."]]' FROM deep_dive_cards d WHERE d.country_id = (SELECT id FROM countries WHERE code = 'AO') AND d.section = 'file_format' AND d.sort_order = 0;
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json)
SELECT d.id, 'fr', 'Format et norme', '[["Le format", "Du JSON, transmis à l''AGT par le logiciel émetteur ou déposé sur le portail du contribuable. Pas de XML : ni profil UBL, ni alignement sur EN 16931."], ["Le réseau", "Aucun. L''Angola n''a pas d''autorité Peppol ni d''échange à quatre coins ; le logiciel dialogue directement avec l''administration."], ["Ce qui le rend valable", "Un code numérique défini par l''AGT au titre de l''article 19(2), apposé par le logiciel agréé, plus un code QR sur le document."], ["Ce que le logiciel doit faire", "Article 17(2) : transmettre en temps réel et ne pas pouvoir supprimer un document émis. Ce sont des conditions de l''agrément, pas des fonctions."]]' FROM deep_dive_cards d WHERE d.country_id = (SELECT id FROM countries WHERE code = 'AO') AND d.section = 'file_format' AND d.sort_order = 0;

