SELECT d.id, 'en', 'Identifiers & registration', '[["The identifier", "The NIF, on both sides of the transaction where the buyer acts in a business capacity. Article 10 requires the supplier''s name, NIF and address in every case."], ["Joining", "Declare the adoption in the Portal do Contribuinte. Only software already certified by the AGT can carry out the steps that follow."], ["Establishments", "Every place that issues a document is registered separately under article 24, before it issues anything."], ["Series", "One per establishment, requested through the certified software and never shared between locations. Next year''s series open from mid-December."]]' FROM deep_dive_cards d WHERE d.country_id = (SELECT id FROM countries WHERE code = 'AO') AND d.section = 'file_format' AND d.sort_order = 1;
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json)
SELECT d.id, 'es', 'Identificadores y registro', '[["El identificador", "El NIF, en ambos lados de la operación cuando el comprador actúa como empresa. El artículo 10 exige siempre nombre, NIF y domicilio del proveedor."], ["La adhesión", "Se declara en el Portal do Contribuinte. Solo un software ya certificado por la AGT puede ejecutar los pasos siguientes."], ["Establecimientos", "Cada lugar que emita documentos se registra por separado según el artículo 24, antes de emitir nada."], ["Series", "Una por establecimiento, solicitada mediante el software certificado y nunca compartida entre locales. Las del año siguiente se abren a mediados de diciembre."]]' FROM deep_dive_cards d WHERE d.country_id = (SELECT id FROM countries WHERE code = 'AO') AND d.section = 'file_format' AND d.sort_order = 1;
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json)
SELECT d.id, 'de', 'Kennungen und Registrierung', '[["Die Kennung", "Die NIF, auf beiden Seiten, wenn der Käufer unternehmerisch handelt. Artikel 10 verlangt in jedem Fall Name, NIF und Anschrift des Lieferanten."], ["Der Beitritt", "Die Teilnahme wird im Portal do Contribuinte erklärt. Nur bereits von der AGT zertifizierte Software kann die folgenden Schritte ausführen."], ["Betriebsstätten", "Jeder Ort, der Dokumente ausstellt, wird nach Artikel 24 gesondert gemeldet, bevor er etwas ausstellt."], ["Serien", "Eine je Betriebsstätte, über die zertifizierte Software beantragt und nie zwischen Standorten geteilt. Serien für das Folgejahr ab Mitte Dezember."]]' FROM deep_dive_cards d WHERE d.country_id = (SELECT id FROM countries WHERE code = 'AO') AND d.section = 'file_format' AND d.sort_order = 1;
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json)
SELECT d.id, 'fr', 'Identifiants et enregistrement', '[["L''identifiant", "Le NIF, des deux côtés lorsque l''acheteur agit en qualité professionnelle. L''article 10 exige toujours le nom, le NIF et l''adresse du fournisseur."], ["L''adhésion", "Elle se déclare sur le Portal do Contribuinte. Seul un logiciel déjà agréé par l''AGT peut accomplir les étapes suivantes."], ["Établissements", "Tout lieu qui émet un document est déclaré séparément au titre de l''article 24, avant toute émission."], ["Séries", "Une par établissement, demandée via le logiciel agréé et jamais partagée entre sites. Les séries de l''année suivante s''ouvrent à la mi-décembre."]]' FROM deep_dive_cards d WHERE d.country_id = (SELECT id FROM countries WHERE code = 'AO') AND d.section = 'file_format' AND d.sort_order = 1;

