SELECT d.id, 'en', 'Mandatory content', '[["Who and what", "Supplier name, NIF and address; the buyer''s details where they act in business; a description of the goods or services with quantities."], ["Numbering", "Sequential and chronological, by document type and by financial year. The series is what makes that possible."], ["Money and tax", "Unit and total price in kwanzas, the price also written out in words, the rate and amount of tax — or the reason no tax was charged."], ["The document''s own trail", "Software identification, a hash code and the printer''s certification number, all under article 10. Portuguese is required."]]' FROM deep_dive_cards d WHERE d.country_id = (SELECT id FROM countries WHERE code = 'AO') AND d.section = 'file_format' AND d.sort_order = 2;
